#include <iostream>
#include <cmath>
using namespace std;

bool is_hazard(int x, int y, int hx, int hy, int safe_dist) {
    return (abs(x - hx) + abs(y - hy)) < safe_dist;
}

int main() {
    int x, y, hx, hy, safe_dist;
    cin >> x >> y >> hx >> hy >> safe_dist;

    bool haz = is_hazard(x, y, hx, hy, safe_dist);
    cout << "HAZARD: " << (haz ? 1 : 0) << endl;
    return 0;
}

