#include <iostream>
#include <cmath>
using namespace std;

int main() {
    int battery, n;
    cin >> battery >> n;

    int cur_x = 0, cur_y = 0;
    bool aborted = false;

    for (int i = 0; i < n; i++) {
        int x, y;
        cin >> x >> y;
        int cost = abs(x - cur_x) + abs(y - cur_y);
        if (cost > battery) {
            cout << "MISSION ABORTED" << endl;
            aborted = true;
            break;
        }
        battery -= cost;
        cur_x = x;
        cur_y = y;
    }

    if (!aborted) {
        cout << "MISSION SUCCESS" << endl;
        cout << "REMAINING BATTERY: " << battery << endl;
        cout << "FINAL POS: (" << cur_x << ", " << cur_y << ")" << endl;
    }

    return 0;
}

